import { Warp, type WarpProps } from "@paper-design/shaders-react";
import { forwardRef, useCallback, useImperativeHandle, useRef, useState, type ComponentProps } from "react";
import { Interactive, Sequence, continueRender, delayRender, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";

const NEUTRAL_COLORS = ["#12121a", "#3a3a5c", "#12121a", "#52527a"];

interface ShaderWarpProps extends Omit<WarpProps, "frame" | "ref"> {}

function ShaderWarpBase({
  speed = 1,
  colors = NEUTRAL_COLORS,
  proportion = 0.5,
  softness = 1,
  distortion = 0.2,
  swirl = 0.4,
  className,
  ...rest
}: ShaderWarpProps) {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const [handle] = useState(() => delayRender("shader-warp"));
  const gate = useCallback(
    (element: HTMLDivElement | null) => {
      if (!element) return;
      requestAnimationFrame(() =>
        requestAnimationFrame(() => continueRender(handle)),
      );
    },
    [handle],
  );

  return (
    <div
      ref={gate}
      className={className}
      style={{ position: "absolute", inset: 0 }}
    >
      <Warp
        speed={0}
        frame={(frame / fps) * speed * 1000}
        colors={colors}
        proportion={proportion}
        softness={softness}
        distortion={distortion}
        swirl={swirl}
        fit="cover"
        width={width}
        height={height}
        {...rest}
      />
    </div>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  distortion: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.2,
    description: "Distortion",
    hiddenFromList: false,
  },
  swirl: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.4,
    description: "Swirl",
    hiddenFromList: false,
  },
  softness: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 1,
    description: "Softness",
    hiddenFromList: false,
  },
  proportion: {
    type: "number",
    min: 0,
    max: 1,
    step: 0.05,
    default: 0.5,
    description: "Proportion",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["speed","distortion","swirl","softness","proportion"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  speed: 1,
  distortion: 0.2,
  swirl: 0.4,
  softness: 1,
  proportion: 0.5,
};

type ShaderWarpElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof ShaderWarpBase>;

const ShaderWarpInner = forwardRef<
  HTMLDivElement,
  ShaderWarpElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<ShaderWarp>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <ShaderWarpBase
          {...(componentProps as unknown as ComponentProps<typeof ShaderWarpBase>)}
        />
      </div>
    </Sequence>
  );
});

export const ShaderWarp = Interactive.withSchema({
  Component: ShaderWarpInner,
  componentName: "<ShaderWarp>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
